inline const char* LookupRuToEn(std::string_view ru_sv) {
    const auto& m = GetRuToEnSvMap();
    auto it = m.find(ru_sv);
    return it != m.end() ? it->second : nullptr;
}

inline QString LookupEnToRu(std::string_view en_sv) {
    const auto& m = GetEnToRuSvMap();
    auto it = m.find(en_sv);
    return it != m.end() ? QString::fromUtf8(it->second) : QString{};
}

inline QString LookupMultiLangSv(std::string_view en_sv, const std::string& lang) {
    const auto& mmap = GetMultiLangSvMap();
    auto it = mmap.find(en_sv);
    if (it == mmap.end()) {
        return {};
    }
    const auto& e = it->second;
    if (lang.rfind("ru", 0) == 0 && e.ru && e.ru[0]) return QString::fromUtf8(e.ru);
    if (lang.rfind("de", 0) == 0 && e.de && e.de[0]) return QString::fromUtf8(e.de);
    if (lang.rfind("fr", 0) == 0 && e.fr && e.fr[0]) return QString::fromUtf8(e.fr);
    if (lang.rfind("es", 0) == 0 && e.es && e.es[0]) return QString::fromUtf8(e.es);
    if (lang.rfind("zh", 0) == 0 && e.zh && e.zh[0]) return QString::fromUtf8(e.zh);
    if (lang.rfind("ja", 0) == 0 && e.ja && e.ja[0]) return QString::fromUtf8(e.ja);
    if (lang.rfind("ar", 0) == 0 && e.ar && e.ar[0]) return QString::fromUtf8(e.ar);
    return {};
}

inline QString LookupMultiLang(const QString& en_key, const std::string& lang) {
    const QByteArray utf8 = en_key.toUtf8();
    return LookupMultiLangSv(std::string_view(utf8.constData(), static_cast<size_t>(utf8.size())), lang);
}

